window.NEXO_LESSONS=[[{"title":"Gêneros textuais","summary":"Textos têm finalidades diferentes: a notícia informa fatos verificáveis; a reportagem aprofunda um tema; a fábula narra uma história que costuma trazer um ensinamento. Observe quem escreve, para quem e com qual objetivo.","example":"Uma notícia responde a perguntas como o quê, quando, onde e quem. Uma receita, por sua vez, orienta ações em etapas.","sections":[{"heading":"Conceitos essenciais","text":"Textos têm finalidades diferentes: a notícia informa fatos verificáveis; a reportagem aprofunda um tema; a fábula narra uma história que costuma trazer um ensinamento."},{"heading":"Como compreender e aplicar","text":"Observe quem escreve, para quem e com qual objetivo."}],"visual":{"icon":"📚","steps":["📖","✍️","🔎"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Uma notícia responde a perguntas como o quê, quando, onde e quem. Uma receita, por sua vez, orienta ações em etapas."},{"title":"Veja outro exemplo","text":"Qual gênero apresenta fatos recentes de interesse público? Resposta: Notícia. A resposta correta é “Notícia”. Observe a função da palavra ou estrutura no enunciado: as outras alternativas não cumprem essa função no contexto apresentado."},{"title":"Teste sua compreensão","text":"Qual gênero costuma apresentar uma moral? Resposta: Fábula. A resposta correta é “Fábula”. Observe a função da palavra ou estrutura no enunciado: as outras alternativas não cumprem essa função no contexto apresentado."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Gramática","summary":"A gramática ajuda a compreender como as palavras se organizam em frases. Substantivos nomeiam seres e ideias; adjetivos atribuem características; verbos indicam ações, estados ou fenômenos.","example":"Em 'As crianças curiosas pesquisam', 'crianças' é substantivo, 'curiosas' é adjetivo e 'pesquisam' é verbo.","sections":[{"heading":"Conceitos essenciais","text":"A gramática ajuda a compreender como as palavras se organizam em frases."},{"heading":"Como compreender e aplicar","text":"Substantivos nomeiam seres e ideias; adjetivos atribuem características; verbos indicam ações, estados ou fenômenos."}],"visual":{"icon":"📚","steps":["📖","✍️","🔎"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Em 'As crianças curiosas pesquisam', 'crianças' é substantivo, 'curiosas' é adjetivo e 'pesquisam' é verbo."},{"title":"Veja outro exemplo","text":"Em “A menina leu”, qual é o substantivo? Resposta: menina. A resposta correta é “menina”. Observe a função da palavra ou estrutura no enunciado: as outras alternativas não cumprem essa função no contexto apresentado."},{"title":"Teste sua compreensão","text":"Em “casa bonita”, qual é o adjetivo? Resposta: bonita. A resposta correta é “bonita”. Observe a função da palavra ou estrutura no enunciado: as outras alternativas não cumprem essa função no contexto apresentado."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Ortografia e pontuação","summary":"A ortografia orienta a escrita convencional das palavras. A pontuação organiza as ideias e ajuda a indicar perguntas, emoções, pausas e falas.","example":"'Você chegou?' é pergunta; 'Você chegou!' pode expressar surpresa. Na escrita, revise acentos e grafias que causam dúvidas.","sections":[{"heading":"Conceitos essenciais","text":"A ortografia orienta a escrita convencional das palavras."},{"heading":"Como compreender e aplicar","text":"A pontuação organiza as ideias e ajuda a indicar perguntas, emoções, pausas e falas."}],"visual":{"icon":"📚","steps":["📖","✍️","🔎"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"'Você chegou?' é pergunta; 'Você chegou!' pode expressar surpresa. Na escrita, revise acentos e grafias que causam dúvidas."},{"title":"Veja outro exemplo","text":"Qual sinal encerra uma pergunta direta? Resposta: ?. A resposta correta é “?”. Observe a função da palavra ou estrutura no enunciado: as outras alternativas não cumprem essa função no contexto apresentado."},{"title":"Teste sua compreensão","text":"Qual sinal indica uma exclamação? Resposta: !. A resposta correta é “!”. Observe a função da palavra ou estrutura no enunciado: as outras alternativas não cumprem essa função no contexto apresentado."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Leitura e interpretação","summary":"Compreender um texto envolve localizar informações explícitas, identificar a ideia principal e inferir o que está sugerido por pistas. Uma inferência precisa ter apoio no texto.","example":"Se alguém pega um guarda-chuva ao ver nuvens escuras, podemos inferir que espera chuva, mas não afirmar que já choveu.","sections":[{"heading":"Conceitos essenciais","text":"Compreender um texto envolve localizar informações explícitas, identificar a ideia principal e inferir o que está sugerido por pistas."},{"heading":"Como compreender e aplicar","text":"Uma inferência precisa ter apoio no texto."}],"visual":{"icon":"📚","steps":["📖","✍️","🔎"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Se alguém pega um guarda-chuva ao ver nuvens escuras, podemos inferir que espera chuva, mas não afirmar que já choveu."},{"title":"Veja outro exemplo","text":"Qual é a ideia principal de um texto? Resposta: Assunto central. A resposta correta é “Assunto central”. Observe a função da palavra ou estrutura no enunciado: as outras alternativas não cumprem essa função no contexto apresentado."},{"title":"Teste sua compreensão","text":"O que é inferir em uma leitura? Resposta: Concluir algo a partir de pistas. A resposta correta é “Concluir algo a partir de pistas”. Observe a função da palavra ou estrutura no enunciado: as outras alternativas não cumprem essa função no contexto apresentado."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Produção textual e coesão","summary":"Escrever bem envolve planejar o assunto, organizar parágrafos, escolher palavras adequadas ao leitor e revisar. Coesão é a ligação entre frases e ideias por conectivos e referências.","example":"'Estudei, portanto compreendi' indica consequência; 'estudei, porém tive dúvidas' indica oposição.","sections":[{"heading":"Conceitos essenciais","text":"Escrever bem envolve planejar o assunto, organizar parágrafos, escolher palavras adequadas ao leitor e revisar."},{"heading":"Como compreender e aplicar","text":"Coesão é a ligação entre frases e ideias por conectivos e referências."}],"visual":{"icon":"📚","steps":["📖","✍️","🔎"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"'Estudei, portanto compreendi' indica consequência; 'estudei, porém tive dúvidas' indica oposição."},{"title":"Veja outro exemplo","text":"Qual etapa vem antes de escrever a versão final? Resposta: Planejamento. A resposta correta é “Planejamento”. Observe a função da palavra ou estrutura no enunciado: as outras alternativas não cumprem essa função no contexto apresentado."},{"title":"Teste sua compreensão","text":"Qual conectivo expressa oposição? Resposta: Porém. A resposta correta é “Porém”. Observe a função da palavra ou estrutura no enunciado: as outras alternativas não cumprem essa função no contexto apresentado."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Classes de palavras","summary":"As classes gramaticais cumprem funções diferentes. Substantivos nomeiam, artigos acompanham nomes, pronomes substituem ou acompanham nomes, adjetivos caracterizam e verbos expressam ações ou estados.","example":"Em 'Aquela menina canta bem', 'aquela' é pronome, 'menina' é substantivo, 'canta' é verbo e 'bem' é advérbio.","sections":[{"heading":"Conceitos essenciais","text":"As classes gramaticais cumprem funções diferentes."},{"heading":"Como compreender e aplicar","text":"Substantivos nomeiam, artigos acompanham nomes, pronomes substituem ou acompanham nomes, adjetivos caracterizam e verbos expressam ações ou estados."}],"visual":{"icon":"📚","steps":["📖","✍️","🔎"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Em 'Aquela menina canta bem', 'aquela' é pronome, 'menina' é substantivo, 'canta' é verbo e 'bem' é advérbio."},{"title":"Veja outro exemplo","text":"Qual palavra é um substantivo próprio? Resposta: Recife. A resposta correta é “Recife”. Observe a função da palavra ou estrutura no enunciado: as outras alternativas não cumprem essa função no contexto apresentado."},{"title":"Teste sua compreensão","text":"Qual palavra é um substantivo coletivo? Resposta: Cardume. A resposta correta é “Cardume”. Observe a função da palavra ou estrutura no enunciado: as outras alternativas não cumprem essa função no contexto apresentado."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Frases, verbos e concordância","summary":"A frase comunica uma ideia; uma oração possui verbo. Em geral, o sujeito indica de quem se fala, e o predicado apresenta uma informação sobre ele. A concordância relaciona palavras em número e pessoa.","example":"Em 'Os alunos estudam', o verbo está no plural para concordar com 'os alunos'.","sections":[{"heading":"Conceitos essenciais","text":"A frase comunica uma ideia; uma oração possui verbo. Em geral, o sujeito indica de quem se fala, e o predicado apresenta uma informação sobre ele."},{"heading":"Como compreender e aplicar","text":"A concordância relaciona palavras em número e pessoa."}],"visual":{"icon":"📚","steps":["📖","✍️","🔎"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Em 'Os alunos estudam', o verbo está no plural para concordar com 'os alunos'."},{"title":"Veja outro exemplo","text":"Em “As crianças brincam”, qual é o sujeito? Resposta: As crianças. A resposta correta é “As crianças”. Observe a função da palavra ou estrutura no enunciado: as outras alternativas não cumprem essa função no contexto apresentado."},{"title":"Teste sua compreensão","text":"Qual é o predicado de “Pedro correu cedo”? Resposta: Correu cedo. A resposta correta é “Correu cedo”. Observe a função da palavra ou estrutura no enunciado: as outras alternativas não cumprem essa função no contexto apresentado."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Literatura e linguagem","summary":"Textos literários podem criar sentidos figurados. A comparação aproxima elementos usando termos como 'como'; a metáfora estabelece uma aproximação sem esse termo; a personificação atribui características humanas a seres ou objetos.","example":"'Rápido como um raio' é comparação; 'o vento sussurrava' é personificação.","sections":[{"heading":"Conceitos essenciais","text":"Textos literários podem criar sentidos figurados."},{"heading":"Como compreender e aplicar","text":"A comparação aproxima elementos usando termos como 'como'; a metáfora estabelece uma aproximação sem esse termo; a personificação atribui características humanas a seres ou objetos."}],"visual":{"icon":"📚","steps":["📖","✍️","🔎"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"'Rápido como um raio' é comparação; 'o vento sussurrava' é personificação."},{"title":"Veja outro exemplo","text":"Qual recurso atribui características humanas a animais? Resposta: Personificação. A resposta correta é “Personificação”. Observe a função da palavra ou estrutura no enunciado: as outras alternativas não cumprem essa função no contexto apresentado."},{"title":"Teste sua compreensão","text":"Qual figura de linguagem compara usando “como”? Resposta: Comparação. A resposta correta é “Comparação”. Observe a função da palavra ou estrutura no enunciado: as outras alternativas não cumprem essa função no contexto apresentado."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Leitura e inferências","summary":"Ler além do explícito é relacionar pistas, contexto e conhecimentos prévios. Uma boa inferência é plausível e pode ser justificada com trechos da leitura.","example":"Se a personagem treme e procura um casaco, pode estar com frio; sem outras pistas, não sabemos a temperatura exata.","sections":[{"heading":"Conceitos essenciais","text":"Ler além do explícito é relacionar pistas, contexto e conhecimentos prévios."},{"heading":"Como compreender e aplicar","text":"Uma boa inferência é plausível e pode ser justificada com trechos da leitura."}],"visual":{"icon":"📚","steps":["📖","✍️","🔎"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Se a personagem treme e procura um casaco, pode estar com frio; sem outras pistas, não sabemos a temperatura exata."},{"title":"Veja outro exemplo","text":"O que é inferir ao ler? Resposta: Concluir algo a partir de pistas. A resposta é “Concluir algo a partir de pistas”. Observe a definição ou a relação apresentada na pergunta."},{"title":"Teste sua compreensão","text":"Em “João pegou o guarda-chuva ao ver nuvens escuras”, o que se infere? Resposta: Ele prevê chuva. A resposta é “Ele prevê chuva”. Observe a definição ou a relação apresentada na pergunta."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Coesão, coerência e conectivos","summary":"Coesão conecta palavras e frases; coerência garante que as ideias façam sentido em conjunto. Conectivos podem indicar causa, consequência, oposição, adição e sequência.","example":"'Porque' costuma apresentar causa; 'porém' indica contraste; 'portanto' pode indicar conclusão.","sections":[{"heading":"Conceitos essenciais","text":"Coesão conecta palavras e frases; coerência garante que as ideias façam sentido em conjunto."},{"heading":"Como compreender e aplicar","text":"Conectivos podem indicar causa, consequência, oposição, adição e sequência."}],"visual":{"icon":"📚","steps":["📖","✍️","🔎"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"'Porque' costuma apresentar causa; 'porém' indica contraste; 'portanto' pode indicar conclusão."},{"title":"Veja outro exemplo","text":"Qual conectivo indica oposição? Resposta: porém. A resposta é “porém”. Observe a definição ou a relação apresentada na pergunta."},{"title":"Teste sua compreensão","text":"Qual conectivo indica causa? Resposta: porque. A resposta é “porque”. Observe a definição ou a relação apresentada na pergunta."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."},{"title":"Produção e revisão textual","summary":"A produção textual envolve planejamento, escrita, releitura e revisão. Revise clareza, organização, pontuação, concordância e adequação ao gênero e ao público.","example":"Antes de entregar uma carta de opinião, verifique se a tese está clara e se os argumentos realmente a sustentam.","sections":[{"heading":"Conceitos essenciais","text":"A produção textual envolve planejamento, escrita, releitura e revisão."},{"heading":"Como compreender e aplicar","text":"Revise clareza, organização, pontuação, concordância e adequação ao gênero e ao público."}],"visual":{"icon":"📚","steps":["📖","✍️","🔎"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Antes de entregar uma carta de opinião, verifique se a tese está clara e se os argumentos realmente a sustentam."},{"title":"Veja outro exemplo","text":"Qual é uma etapa importante antes de escrever? Resposta: Planejar o texto. A resposta é “Planejar o texto”. Observe a definição ou a relação apresentada na pergunta."},{"title":"Teste sua compreensão","text":"Na revisão, o que devemos verificar? Resposta: Clareza e pontuação. A resposta é “Clareza e pontuação”. Observe a definição ou a relação apresentada na pergunta."}],"studyTip":"Identifique a ideia principal, observe as palavras-chave e explique com suas próprias palavras."}],[{"title":"Operações","summary":"Adição reúne quantidades; subtração calcula diferenças; multiplicação representa parcelas iguais; divisão distribui ou mede agrupamentos. Em problemas, identifique os dados e a pergunta antes de calcular.","example":"Se há 4 caixas com 6 lápis, são 4 × 6 = 24 lápis. Ao distribuir igualmente entre 3 crianças, cada uma recebe 8.","sections":[{"heading":"Conceitos essenciais","text":"Adição reúne quantidades; subtração calcula diferenças; multiplicação representa parcelas iguais; divisão distribui ou mede agrupamentos."},{"heading":"Como compreender e aplicar","text":"Em problemas, identifique os dados e a pergunta antes de calcular."}],"visual":{"icon":"🔢","steps":["🧮","📐","💡"],"labels":["OBSERVAR","CALCULAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Se há 4 caixas com 6 lápis, são 4 × 6 = 24 lápis. Ao distribuir igualmente entre 3 crianças, cada uma recebe 8."},{"title":"Veja outro exemplo","text":"Quanto é 48 + 27? Resposta: 75. A resposta correta é “75”. Confira a operação e suas etapas antes de escolher; uma resposta próxima não substitui o cálculo."},{"title":"Teste sua compreensão","text":"Quanto é 93 − 46? Resposta: 47. A resposta correta é “47”. Confira a operação e suas etapas antes de escolher; uma resposta próxima não substitui o cálculo."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Frações e decimais","summary":"Frações representam partes de um todo dividido em partes iguais. O denominador indica em quantas partes o todo foi dividido; o numerador, quantas partes consideramos. Números decimais também representam partes da unidade.","example":"1/2 = 0,5 e 1/4 = 0,25. Para somar 1/2 + 1/4, reescreva 1/2 como 2/4: o resultado é 3/4.","sections":[{"heading":"Conceitos essenciais","text":"Frações representam partes de um todo dividido em partes iguais. O denominador indica em quantas partes o todo foi dividido; o numerador, quantas partes consideramos."},{"heading":"Como compreender e aplicar","text":"Números decimais também representam partes da unidade."}],"visual":{"icon":"🔢","steps":["🧮","📐","💡"],"labels":["LER","CALCULAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"1/2 = 0,5 e 1/4 = 0,25. Para somar 1/2 + 1/4, reescreva 1/2 como 2/4: o resultado é 3/4."},{"title":"Veja outro exemplo","text":"Quanto é 1/2 de 20? Resposta: 10. A resposta correta é “10”. Confira a operação e suas etapas antes de escolher; uma resposta próxima não substitui o cálculo."},{"title":"Teste sua compreensão","text":"Qual fração equivale a 2/4? Resposta: 1/2. A resposta correta é “1/2”. Confira a operação e suas etapas antes de escolher; uma resposta próxima não substitui o cálculo."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Geometria e medidas","summary":"Figuras planas têm lados, vértices e ângulos. Perímetro é a medida do contorno; área é a medida da superfície. Atenção às unidades: comprimento em cm ou m; área em cm² ou m².","example":"Um retângulo de 6 m por 4 m tem área 24 m² e perímetro 20 m.","sections":[{"heading":"Conceitos essenciais","text":"Figuras planas têm lados, vértices e ângulos. Perímetro é a medida do contorno; área é a medida da superfície."},{"heading":"Como compreender e aplicar","text":"Atenção às unidades: comprimento em cm ou m; área em cm² ou m²."}],"visual":{"icon":"🔢","steps":["🧮","📐","💡"],"labels":["OBSERVAR","CALCULAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Um retângulo de 6 m por 4 m tem área 24 m² e perímetro 20 m."},{"title":"Veja outro exemplo","text":"Quantos lados tem um hexágono? Resposta: 6. A resposta correta é “6”. Confira a operação e suas etapas antes de escolher; uma resposta próxima não substitui o cálculo."},{"title":"Teste sua compreensão","text":"Qual é o perímetro de um quadrado de lado 5 cm? Resposta: 20 cm. A resposta correta é “20 cm”. Confira a operação e suas etapas antes de escolher; uma resposta próxima não substitui o cálculo."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Sistema de numeração","summary":"No sistema decimal, cada posição vale dez vezes a posição à direita. Unidades, dezenas, centenas e milhares ajudam a ler, compor e decompor números.","example":"Em 34.205, o algarismo 4 vale 4.000, e o algarismo 2 vale 200.","sections":[{"heading":"Conceitos essenciais","text":"No sistema decimal, cada posição vale dez vezes a posição à direita."},{"heading":"Como compreender e aplicar","text":"Unidades, dezenas, centenas e milhares ajudam a ler, compor e decompor números."}],"visual":{"icon":"🔢","steps":["🧮","📐","💡"],"labels":["LER","CALCULAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Em 34.205, o algarismo 4 vale 4.000, e o algarismo 2 vale 200."},{"title":"Veja outro exemplo","text":"Quanto vale o algarismo 7 em 7.432? Resposta: 7.000. A resposta correta é “7.000”. Confira a operação e suas etapas antes de escolher; uma resposta próxima não substitui o cálculo."},{"title":"Teste sua compreensão","text":"Qual número representa três milhares e duas dezenas? Resposta: 3.020. A resposta correta é “3.020”. Confira a operação e suas etapas antes de escolher; uma resposta próxima não substitui o cálculo."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Múltiplos e divisores","summary":"Múltiplos surgem da multiplicação por números inteiros; divisores dividem um número sem deixar resto. O MMC ajuda em situações de coincidência de ciclos; o MDC, na formação de grupos iguais maiores.","example":"Os múltiplos de 6 incluem 6, 12, 18 e 24. Como 24 também é múltiplo de 8, MMC(6,8)=24.","sections":[{"heading":"Conceitos essenciais","text":"Múltiplos surgem da multiplicação por números inteiros; divisores dividem um número sem deixar resto."},{"heading":"Como compreender e aplicar","text":"O MMC ajuda em situações de coincidência de ciclos; o MDC, na formação de grupos iguais maiores."}],"visual":{"icon":"🔢","steps":["🧮","📐","💡"],"labels":["OBSERVAR","CALCULAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Os múltiplos de 6 incluem 6, 12, 18 e 24. Como 24 também é múltiplo de 8, MMC(6,8)=24."},{"title":"Veja outro exemplo","text":"Qual número é múltiplo de 6? Resposta: 42. A resposta correta é “42”. Confira a operação e suas etapas antes de escolher; uma resposta próxima não substitui o cálculo."},{"title":"Teste sua compreensão","text":"Qual número é divisor de 36? Resposta: 9. A resposta correta é “9”. Confira a operação e suas etapas antes de escolher; uma resposta próxima não substitui o cálculo."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Porcentagem","summary":"Porcentagem significa 'a cada cem'. Para calcular uma porcentagem, transforme-a em fração centesimal ou decimal e multiplique pelo valor total.","example":"15% de 200 = 0,15 × 200 = 30. Um desconto de R$ 30 em R$ 200 deixa o preço em R$ 170.","sections":[{"heading":"Conceitos essenciais","text":"Porcentagem significa 'a cada cem'."},{"heading":"Como compreender e aplicar","text":"Para calcular uma porcentagem, transforme-a em fração centesimal ou decimal e multiplique pelo valor total."}],"visual":{"icon":"🔢","steps":["🧮","📐","💡"],"labels":["LER","CALCULAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"15% de 200 = 0,15 × 200 = 30. Um desconto de R$ 30 em R$ 200 deixa o preço em R$ 170."},{"title":"Veja outro exemplo","text":"Quanto é 10% de 200? Resposta: 20. A resposta correta é “20”. Confira a operação e suas etapas antes de escolher; uma resposta próxima não substitui o cálculo."},{"title":"Teste sua compreensão","text":"Quanto é 25% de 80? Resposta: 20. A resposta correta é “20”. Confira a operação e suas etapas antes de escolher; uma resposta próxima não substitui o cálculo."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Álgebra e sequências","summary":"Sequências seguem padrões que podem ser descritos por regras. Letras podem representar valores desconhecidos; equações relacionam expressões iguais.","example":"Na sequência 3, 7, 11, 15, a regra é somar 4. Em x + 7 = 20, x = 13.","sections":[{"heading":"Conceitos essenciais","text":"Sequências seguem padrões que podem ser descritos por regras."},{"heading":"Como compreender e aplicar","text":"Letras podem representar valores desconhecidos; equações relacionam expressões iguais."}],"visual":{"icon":"🔢","steps":["🧮","📐","💡"],"labels":["OBSERVAR","CALCULAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Na sequência 3, 7, 11, 15, a regra é somar 4. Em x + 7 = 20, x = 13."},{"title":"Veja outro exemplo","text":"Qual é o próximo termo de 2, 4, 6, 8...? Resposta: 10. A resposta correta é “10”. Confira a operação e suas etapas antes de escolher; uma resposta próxima não substitui o cálculo."},{"title":"Teste sua compreensão","text":"Qual é o próximo termo de 3, 6, 12, 24...? Resposta: 48. A resposta correta é “48”. Confira a operação e suas etapas antes de escolher; uma resposta próxima não substitui o cálculo."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Estatística e probabilidade","summary":"A estatística organiza e interpreta dados por tabelas, gráficos e medidas como a média. A probabilidade compara casos favoráveis com todos os resultados igualmente possíveis.","example":"A média de 4, 6 e 8 é (4+6+8)/3=6. Em um dado justo, a chance de sair 2 é 1/6.","sections":[{"heading":"Conceitos essenciais","text":"A estatística organiza e interpreta dados por tabelas, gráficos e medidas como a média."},{"heading":"Como compreender e aplicar","text":"A probabilidade compara casos favoráveis com todos os resultados igualmente possíveis."}],"visual":{"icon":"🔢","steps":["🧮","📐","💡"],"labels":["LER","CALCULAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"A média de 4, 6 e 8 é (4+6+8)/3=6. Em um dado justo, a chance de sair 2 é 1/6."},{"title":"Veja outro exemplo","text":"Qual gráfico é adequado para comparar quantidades por categorias? Resposta: Gráfico de barras. A resposta correta é “Gráfico de barras”. Confira a operação e suas etapas antes de escolher; uma resposta próxima não substitui o cálculo."},{"title":"Teste sua compreensão","text":"Qual é a média de 4, 6 e 8? Resposta: 6. A resposta correta é “6”. Confira a operação e suas etapas antes de escolher; uma resposta próxima não substitui o cálculo."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Expressões numéricas","summary":"Uma expressão reúne operações. Resolva primeiro parênteses; depois potências, multiplicações e divisões; por fim, adições e subtrações, respeitando a ordem da esquerda para a direita quando necessário.","example":"5 + 3 × 4 = 5 + 12 = 17, não 32.","sections":[{"heading":"Conceitos essenciais","text":"Uma expressão reúne operações."},{"heading":"Como compreender e aplicar","text":"Resolva primeiro parênteses; depois potências, multiplicações e divisões; por fim, adições e subtrações, respeitando a ordem da esquerda para a direita quando necessário."}],"visual":{"icon":"🔢","steps":["🧮","📐","💡"],"labels":["OBSERVAR","CALCULAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"5 + 3 × 4 = 5 + 12 = 17, não 32."},{"title":"Veja outro exemplo","text":"Quanto é 5 + 3 × 4? Resposta: 17. A resposta é “17”. Observe a definição ou a relação apresentada na pergunta."},{"title":"Teste sua compreensão","text":"Quanto é 7 + 2 × 6? Resposta: 19. A resposta é “19”. Observe a definição ou a relação apresentada na pergunta."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Razões, porcentagens e descontos","summary":"Razão compara grandezas por divisão. Descontos e acréscimos percentuais são calculados em relação a um valor de referência. Sempre identifique qual é o valor inicial.","example":"20% de R$ 150 são R$ 30. Após o desconto, o produto custa R$ 120.","sections":[{"heading":"Conceitos essenciais","text":"Razão compara grandezas por divisão. Descontos e acréscimos percentuais são calculados em relação a um valor de referência."},{"heading":"Como compreender e aplicar","text":"Sempre identifique qual é o valor inicial."}],"visual":{"icon":"🔢","steps":["🧮","📐","💡"],"labels":["LER","CALCULAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"20% de R$ 150 são R$ 30. Após o desconto, o produto custa R$ 120."},{"title":"Veja outro exemplo","text":"Quanto é 10% de 80? Resposta: 8. A resposta é “8”. Observe a definição ou a relação apresentada na pergunta."},{"title":"Teste sua compreensão","text":"Quanto é 25% de 200? Resposta: 50. A resposta é “50”. Observe a definição ou a relação apresentada na pergunta."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."},{"title":"Plano cartesiano","summary":"O plano cartesiano usa dois eixos perpendiculares. Um ponto é representado por (x,y): x é a posição horizontal, y é a vertical. Os sinais indicam a direção em relação à origem.","example":"O ponto (−2,3) fica duas unidades à esquerda e três acima da origem.","sections":[{"heading":"Conceitos essenciais","text":"O plano cartesiano usa dois eixos perpendiculares. Um ponto é representado por (x,y): x é a posição horizontal, y é a vertical."},{"heading":"Como compreender e aplicar","text":"Os sinais indicam a direção em relação à origem."}],"visual":{"icon":"🔢","steps":["🧮","📐","💡"],"labels":["OBSERVAR","CALCULAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"O ponto (−2,3) fica duas unidades à esquerda e três acima da origem."},{"title":"Veja outro exemplo","text":"Qual é a abscissa de (3, 5)? Resposta: 3. A resposta é “3”. Observe a definição ou a relação apresentada na pergunta."},{"title":"Teste sua compreensão","text":"Qual é a ordenada de (−2, 4)? Resposta: 4. A resposta é “4”. Observe a definição ou a relação apresentada na pergunta."}],"studyTip":"Separe os dados, escolha a operação ou representação e confira se o resultado faz sentido."}],[{"title":"Matéria e misturas","summary":"Matéria é tudo que possui massa e ocupa espaço. Misturas homogêneas apresentam aspecto uniforme; heterogêneas mostram mais de uma fase. A separação depende das propriedades dos componentes.","example":"Água e óleo formam mistura heterogênea; sal dissolvido em água forma mistura homogênea. Filtração separa sólidos insolúveis de líquidos.","sections":[{"heading":"Conceitos essenciais","text":"Matéria é tudo que possui massa e ocupa espaço. Misturas homogêneas apresentam aspecto uniforme; heterogêneas mostram mais de uma fase."},{"heading":"Como compreender e aplicar","text":"A separação depende das propriedades dos componentes."}],"visual":{"icon":"🔬","steps":["🔬","🧬","🌱"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Água e óleo formam mistura heterogênea; sal dissolvido em água forma mistura homogênea. Filtração separa sólidos insolúveis de líquidos."},{"title":"Veja outro exemplo","text":"Água e óleo formam qual tipo de mistura? Resposta: heterogênea. A resposta correta é “heterogênea”. Relacione a definição científica à função ou ao fenômeno indicado na pergunta."},{"title":"Teste sua compreensão","text":"Água e sal totalmente dissolvido formam mistura... Resposta: homogênea. A resposta correta é “homogênea”. Relacione a definição científica à função ou ao fenômeno indicado na pergunta."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Células e corpo humano","summary":"A célula é unidade básica dos seres vivos. Células formam tecidos; tecidos formam órgãos; órgãos integram sistemas que atuam juntos para manter o organismo.","example":"O sistema nervoso recebe e processa informações, enquanto o circulatório transporta substâncias pelo corpo.","sections":[{"heading":"Conceitos essenciais","text":"A célula é unidade básica dos seres vivos."},{"heading":"Como compreender e aplicar","text":"Células formam tecidos; tecidos formam órgãos; órgãos integram sistemas que atuam juntos para manter o organismo."}],"visual":{"icon":"🔬","steps":["🔬","🧬","🌱"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"O sistema nervoso recebe e processa informações, enquanto o circulatório transporta substâncias pelo corpo."},{"title":"Veja outro exemplo","text":"Qual é a unidade básica dos seres vivos? Resposta: célula. A resposta correta é “célula”. Relacione a definição científica à função ou ao fenômeno indicado na pergunta."},{"title":"Teste sua compreensão","text":"Qual órgão coordena muitas funções do sistema nervoso? Resposta: cérebro. A resposta correta é “cérebro”. Relacione a definição científica à função ou ao fenômeno indicado na pergunta."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Terra e Universo","summary":"A Terra possui crosta, manto e núcleo. Rochas e fósseis ajudam a investigar a história do planeta. A Terra realiza rotação e translação, movimentos com efeitos observáveis.","example":"A rotação explica a alternância de dias e noites; fósseis registram vestígios ou restos de seres do passado.","sections":[{"heading":"Conceitos essenciais","text":"A Terra possui crosta, manto e núcleo. Rochas e fósseis ajudam a investigar a história do planeta."},{"heading":"Como compreender e aplicar","text":"A Terra realiza rotação e translação, movimentos com efeitos observáveis."}],"visual":{"icon":"🔬","steps":["🔬","🧬","🌱"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"A rotação explica a alternância de dias e noites; fósseis registram vestígios ou restos de seres do passado."},{"title":"Veja outro exemplo","text":"Qual camada da Terra é a mais externa e sólida? Resposta: crosta. A resposta correta é “crosta”. Relacione a definição científica à função ou ao fenômeno indicado na pergunta."},{"title":"Teste sua compreensão","text":"Fósseis ajudam a estudar... Resposta: seres vivos do passado. A resposta correta é “seres vivos do passado”. Relacione a definição científica à função ou ao fenômeno indicado na pergunta."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Células e seres vivos","summary":"Seres vivos são formados por células. A membrana controla trocas com o ambiente; o citoplasma abriga estruturas celulares; o material genético contém informações hereditárias.","example":"Células vegetais têm parede celular e, em muitos tecidos, cloroplastos relacionados à fotossíntese.","sections":[{"heading":"Conceitos essenciais","text":"Seres vivos são formados por células."},{"heading":"Como compreender e aplicar","text":"A membrana controla trocas com o ambiente; o citoplasma abriga estruturas celulares; o material genético contém informações hereditárias."}],"visual":{"icon":"🔬","steps":["🔬","🧬","🌱"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Células vegetais têm parede celular e, em muitos tecidos, cloroplastos relacionados à fotossíntese."},{"title":"Veja outro exemplo","text":"Qual é a unidade básica dos seres vivos? Resposta: Célula. A resposta correta é “Célula”. Relacione a definição científica à função ou ao fenômeno indicado na pergunta."},{"title":"Teste sua compreensão","text":"Qual estrutura controla muitas atividades celulares? Resposta: Núcleo. A resposta correta é “Núcleo”. Relacione a definição científica à função ou ao fenômeno indicado na pergunta."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Sistema nervoso e sentidos","summary":"O sistema nervoso integra informações recebidas pelos órgãos dos sentidos e coordena respostas. Neurônios transmitem sinais; cérebro, medula e nervos atuam de forma articulada.","example":"Ao tocar algo quente, uma resposta reflexa pode retirar rapidamente a mão, ajudando na proteção.","sections":[{"heading":"Conceitos essenciais","text":"O sistema nervoso integra informações recebidas pelos órgãos dos sentidos e coordena respostas."},{"heading":"Como compreender e aplicar","text":"Neurônios transmitem sinais; cérebro, medula e nervos atuam de forma articulada."}],"visual":{"icon":"🔬","steps":["🔬","🧬","🌱"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Ao tocar algo quente, uma resposta reflexa pode retirar rapidamente a mão, ajudando na proteção."},{"title":"Veja outro exemplo","text":"Qual órgão coordena muitas funções do sistema nervoso? Resposta: Encéfalo. A resposta correta é “Encéfalo”. Relacione a definição científica à função ou ao fenômeno indicado na pergunta."},{"title":"Teste sua compreensão","text":"Qual estrutura transmite impulsos nervosos? Resposta: Neurônio. A resposta correta é “Neurônio”. Relacione a definição científica à função ou ao fenômeno indicado na pergunta."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Sistema locomotor","summary":"O movimento depende da atuação conjunta de ossos, músculos e articulações. Ossos dão sustentação e proteção; músculos se contraem para movimentar partes do corpo.","example":"Ao dobrar o braço, músculos atuam de forma coordenada. Boa postura e atividades adequadas ajudam a preservar o sistema.","sections":[{"heading":"Conceitos essenciais","text":"O movimento depende da atuação conjunta de ossos, músculos e articulações."},{"heading":"Como compreender e aplicar","text":"Ossos dão sustentação e proteção; músculos se contraem para movimentar partes do corpo."}],"visual":{"icon":"🔬","steps":["🔬","🧬","🌱"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Ao dobrar o braço, músculos atuam de forma coordenada. Boa postura e atividades adequadas ajudam a preservar o sistema."},{"title":"Veja outro exemplo","text":"Qual tecido forma os ossos? Resposta: Tecido ósseo. A resposta correta é “Tecido ósseo”. Relacione a definição científica à função ou ao fenômeno indicado na pergunta."},{"title":"Teste sua compreensão","text":"Qual é uma função do esqueleto? Resposta: Sustentar o corpo. A resposta correta é “Sustentar o corpo”. Relacione a definição científica à função ou ao fenômeno indicado na pergunta."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Terra, rochas e fósseis","summary":"Rochas podem ser ígneas, sedimentares ou metamórficas, conforme sua formação. Fósseis encontrados em camadas sedimentares ajudam a reconstruir ambientes antigos.","example":"Camadas inferiores não deformadas geralmente são mais antigas que as superiores, mas a análise geológica considera exceções.","sections":[{"heading":"Conceitos essenciais","text":"Rochas podem ser ígneas, sedimentares ou metamórficas, conforme sua formação."},{"heading":"Como compreender e aplicar","text":"Fósseis encontrados em camadas sedimentares ajudam a reconstruir ambientes antigos."}],"visual":{"icon":"🔬","steps":["🔬","🧬","🌱"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Camadas inferiores não deformadas geralmente são mais antigas que as superiores, mas a análise geológica considera exceções."},{"title":"Veja outro exemplo","text":"Qual é a camada mais externa da Terra? Resposta: Crosta. A resposta correta é “Crosta”. Relacione a definição científica à função ou ao fenômeno indicado na pergunta."},{"title":"Teste sua compreensão","text":"Qual camada fica abaixo da crosta terrestre? Resposta: Manto. A resposta correta é “Manto”. Relacione a definição científica à função ou ao fenômeno indicado na pergunta."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Movimentos da Terra","summary":"A rotação é o giro da Terra em torno de seu eixo, durando aproximadamente 24 horas. A translação é o movimento ao redor do Sol; junto da inclinação do eixo, relaciona-se às estações.","example":"Quando um lado da Terra recebe luz solar, o outro pode estar à noite. As estações não dependem apenas da distância ao Sol.","sections":[{"heading":"Conceitos essenciais","text":"A rotação é o giro da Terra em torno de seu eixo, durando aproximadamente 24 horas."},{"heading":"Como compreender e aplicar","text":"A translação é o movimento ao redor do Sol; junto da inclinação do eixo, relaciona-se às estações."}],"visual":{"icon":"🔬","steps":["🔬","🧬","🌱"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Quando um lado da Terra recebe luz solar, o outro pode estar à noite. As estações não dependem apenas da distância ao Sol."},{"title":"Veja outro exemplo","text":"Qual movimento causa a alternância de dias e noites? Resposta: Rotação. A resposta correta é “Rotação”. Relacione a definição científica à função ou ao fenômeno indicado na pergunta."},{"title":"Teste sua compreensão","text":"Quanto dura aproximadamente uma rotação da Terra? Resposta: 24 horas. A resposta correta é “24 horas”. Relacione a definição científica à função ou ao fenômeno indicado na pergunta."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Sistemas do corpo e saúde","summary":"Sistemas respiratório, digestório, circulatório, nervoso e locomotor atuam de forma integrada. Sono, alimentação, higiene e movimento contribuem para a saúde.","example":"Durante exercício, o corpo necessita de mais oxigênio e nutrientes, e a respiração e a frequência cardíaca podem aumentar.","sections":[{"heading":"Conceitos essenciais","text":"Sistemas respiratório, digestório, circulatório, nervoso e locomotor atuam de forma integrada."},{"heading":"Como compreender e aplicar","text":"Sono, alimentação, higiene e movimento contribuem para a saúde."}],"visual":{"icon":"🔬","steps":["🔬","🧬","🌱"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Durante exercício, o corpo necessita de mais oxigênio e nutrientes, e a respiração e a frequência cardíaca podem aumentar."},{"title":"Veja outro exemplo","text":"Qual sistema transporta sangue pelo corpo? Resposta: Circulatório. A resposta é “Circulatório”. Observe a definição ou a relação apresentada na pergunta."},{"title":"Teste sua compreensão","text":"Qual órgão bombeia o sangue? Resposta: Coração. A resposta é “Coração”. Observe a definição ou a relação apresentada na pergunta."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."},{"title":"Ecossistemas e relações ambientais","summary":"Ecossistema reúne seres vivos e componentes não vivos em interação. Produtores captam energia, consumidores obtêm alimento de outros organismos e decompositores reciclam matéria.","example":"Em uma cadeia alimentar, capim → gafanhoto → sapo, o capim é produtor. A redução de uma população pode afetar outras.","sections":[{"heading":"Conceitos essenciais","text":"Ecossistema reúne seres vivos e componentes não vivos em interação."},{"heading":"Como compreender e aplicar","text":"Produtores captam energia, consumidores obtêm alimento de outros organismos e decompositores reciclam matéria."}],"visual":{"icon":"🔬","steps":["🔬","🧬","🌱"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Em uma cadeia alimentar, capim → gafanhoto → sapo, o capim é produtor. A redução de uma população pode afetar outras."},{"title":"Veja outro exemplo","text":"Quem produz alimento por fotossíntese? Resposta: Plantas verdes. A resposta é “Plantas verdes”. Observe a definição ou a relação apresentada na pergunta."},{"title":"Teste sua compreensão","text":"Qual é um consumidor primário comum? Resposta: Coelho herbívoro. A resposta é “Coelho herbívoro”. Observe a definição ou a relação apresentada na pergunta."}],"studyTip":"Observe o fenômeno, relacione causas e efeitos e compare as evidências."}],[{"title":"Fontes e tempo histórico","summary":"Historiadores investigam mudanças e permanências usando fontes escritas, orais, visuais e materiais. Uma fonte precisa ser analisada considerando autoria, época, finalidade e contexto.","example":"Uma fotografia antiga mostra aspectos do passado, mas não explica sozinha todos os acontecimentos retratados.","sections":[{"heading":"Conceitos essenciais","text":"Historiadores investigam mudanças e permanências usando fontes escritas, orais, visuais e materiais."},{"heading":"Como compreender e aplicar","text":"Uma fonte precisa ser analisada considerando autoria, época, finalidade e contexto."}],"visual":{"icon":"🏛️","steps":["🏺","📜","🕰️"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Uma fotografia antiga mostra aspectos do passado, mas não explica sozinha todos os acontecimentos retratados."},{"title":"Veja outro exemplo","text":"Qual é um exemplo de fonte histórica escrita? Resposta: carta antiga. A resposta correta é “carta antiga”. Considere o contexto histórico, as evidências e a época citada; evite generalizações."},{"title":"Teste sua compreensão","text":"Qual profissional investiga sociedades do passado? Resposta: historiador. A resposta correta é “historiador”. Considere o contexto histórico, as evidências e a época citada; evite generalizações."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Primeiras sociedades","summary":"Grupos humanos viveram de diferentes maneiras ao longo do tempo. O nomadismo envolve deslocamentos frequentes; em várias regiões, agricultura e criação de animais favoreceram assentamentos permanentes.","example":"O cultivo de alimentos e seu armazenamento ajudaram na formação de aldeias, sem que todos os povos adotassem o mesmo modo de vida.","sections":[{"heading":"Conceitos essenciais","text":"Grupos humanos viveram de diferentes maneiras ao longo do tempo."},{"heading":"Como compreender e aplicar","text":"O nomadismo envolve deslocamentos frequentes; em várias regiões, agricultura e criação de animais favoreceram assentamentos permanentes."}],"visual":{"icon":"🏛️","steps":["🏺","📜","🕰️"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"O cultivo de alimentos e seu armazenamento ajudaram na formação de aldeias, sem que todos os povos adotassem o mesmo modo de vida."},{"title":"Veja outro exemplo","text":"O que significa nomadismo? Resposta: deslocar-se entre lugares. A resposta correta é “deslocar-se entre lugares”. Considere o contexto histórico, as evidências e a época citada; evite generalizações."},{"title":"Teste sua compreensão","text":"Qual atividade favoreceu o sedentarismo? Resposta: agricultura. A resposta correta é “agricultura”. Considere o contexto histórico, as evidências e a época citada; evite generalizações."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Civilizações antigas","summary":"Civilizações antigas desenvolveram formas diversas de governo, religião, escrita e trabalho. Rios favoreceram agricultura e circulação, mas cada sociedade tinha características próprias.","example":"O Nilo foi importante no Egito Antigo; Tigre e Eufrates, na Mesopotâmia.","sections":[{"heading":"Conceitos essenciais","text":"Civilizações antigas desenvolveram formas diversas de governo, religião, escrita e trabalho."},{"heading":"Como compreender e aplicar","text":"Rios favoreceram agricultura e circulação, mas cada sociedade tinha características próprias."}],"visual":{"icon":"🏛️","steps":["🏺","📜","🕰️"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"O Nilo foi importante no Egito Antigo; Tigre e Eufrates, na Mesopotâmia."},{"title":"Veja outro exemplo","text":"Qual rio foi fundamental ao Egito Antigo? Resposta: Nilo. A resposta correta é “Nilo”. Considere o contexto histórico, as evidências e a época citada; evite generalizações."},{"title":"Teste sua compreensão","text":"Em qual região floresceu a Mesopotâmia? Resposta: entre Tigre e Eufrates. A resposta correta é “entre Tigre e Eufrates”. Considere o contexto histórico, as evidências e a época citada; evite generalizações."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Fontes e tempo histórico","summary":"A história não é uma lista de datas: envolve processos, diferentes durações e perspectivas. Fontes históricas podem apresentar versões distintas de um mesmo fato.","example":"Cartas, relatos orais e objetos antigos devem ser comparados e situados no tempo.","sections":[{"heading":"Conceitos essenciais","text":"A história não é uma lista de datas: envolve processos, diferentes durações e perspectivas."},{"heading":"Como compreender e aplicar","text":"Fontes históricas podem apresentar versões distintas de um mesmo fato."}],"visual":{"icon":"🏛️","steps":["🏺","📜","🕰️"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Cartas, relatos orais e objetos antigos devem ser comparados e situados no tempo."},{"title":"Veja outro exemplo","text":"Qual é um exemplo de fonte histórica escrita? Resposta: Carta antiga. A resposta correta é “Carta antiga”. Considere o contexto histórico, as evidências e a época citada; evite generalizações."},{"title":"Teste sua compreensão","text":"Qual é uma fonte histórica oral? Resposta: Depoimento. A resposta correta é “Depoimento”. Considere o contexto histórico, as evidências e a época citada; evite generalizações."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Primeiros humanos","summary":"A história dos primeiros humanos é estudada com fósseis, ferramentas e outros vestígios. A fabricação de instrumentos, as migrações e a domesticação de plantas ocorreram em contextos diversos.","example":"Pinturas rupestres e utensílios ajudam a compreender atividades e formas de expressão de grupos antigos.","sections":[{"heading":"Conceitos essenciais","text":"A história dos primeiros humanos é estudada com fósseis, ferramentas e outros vestígios."},{"heading":"Como compreender e aplicar","text":"A fabricação de instrumentos, as migrações e a domesticação de plantas ocorreram em contextos diversos."}],"visual":{"icon":"🏛️","steps":["🏺","📜","🕰️"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Pinturas rupestres e utensílios ajudam a compreender atividades e formas de expressão de grupos antigos."},{"title":"Veja outro exemplo","text":"Qual característica marca o nomadismo? Resposta: Deslocamento frequente em busca de recursos. A resposta correta é “Deslocamento frequente em busca de recursos”. Considere o contexto histórico, as evidências e a época citada; evite generalizações."},{"title":"Teste sua compreensão","text":"Qual mudança favoreceu o sedentarismo? Resposta: Agricultura. A resposta correta é “Agricultura”. Considere o contexto histórico, as evidências e a época citada; evite generalizações."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Mesopotâmia e Egito","summary":"Mesopotâmia e Egito desenvolveram sociedades complexas ligadas ao uso da água e à agricultura. Governos, crenças, trabalhos e formas de escrita variaram entre elas.","example":"Os mesopotâmicos desenvolveram escrita cuneiforme; no Egito Antigo, usaram-se hieróglifos em determinados contextos.","sections":[{"heading":"Conceitos essenciais","text":"Mesopotâmia e Egito desenvolveram sociedades complexas ligadas ao uso da água e à agricultura."},{"heading":"Como compreender e aplicar","text":"Governos, crenças, trabalhos e formas de escrita variaram entre elas."}],"visual":{"icon":"🏛️","steps":["🏺","📜","🕰️"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Os mesopotâmicos desenvolveram escrita cuneiforme; no Egito Antigo, usaram-se hieróglifos em determinados contextos."},{"title":"Veja outro exemplo","text":"Entre quais rios floresceu a Mesopotâmia? Resposta: Tigre e Eufrates. A resposta correta é “Tigre e Eufrates”. Considere o contexto histórico, as evidências e a época citada; evite generalizações."},{"title":"Teste sua compreensão","text":"Qual rio foi fundamental ao Egito Antigo? Resposta: Nilo. A resposta correta é “Nilo”. Considere o contexto histórico, as evidências e a época citada; evite generalizações."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Grécia e Roma","summary":"As sociedades grega e romana influenciaram instituições, artes e leis, mas seus direitos eram restritos a grupos específicos. A democracia ateniense antiga não incluía todos os habitantes.","example":"Atenas ficou associada à democracia de cidadãos; Roma passou por monarquia, república e império.","sections":[{"heading":"Conceitos essenciais","text":"As sociedades grega e romana influenciaram instituições, artes e leis, mas seus direitos eram restritos a grupos específicos."},{"heading":"Como compreender e aplicar","text":"A democracia ateniense antiga não incluía todos os habitantes."}],"visual":{"icon":"🏛️","steps":["🏺","📜","🕰️"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Atenas ficou associada à democracia de cidadãos; Roma passou por monarquia, república e império."},{"title":"Veja outro exemplo","text":"Qual cidade grega é associada à democracia antiga? Resposta: Atenas. A resposta correta é “Atenas”. Considere o contexto histórico, as evidências e a época citada; evite generalizações."},{"title":"Teste sua compreensão","text":"Qual cidade grega ficou conhecida pela formação militar? Resposta: Esparta. A resposta correta é “Esparta”. Considere o contexto histórico, as evidências e a época citada; evite generalizações."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Povos indígenas e Américas","summary":"As Américas abrigavam sociedades muito diversas antes da colonização europeia. Povos desenvolveram técnicas agrícolas, cidades, redes de troca, conhecimentos e tradições.","example":"Maias, astecas e incas possuíam organizações distintas. Não devemos tratar todos os povos indígenas como um único grupo.","sections":[{"heading":"Conceitos essenciais","text":"As Américas abrigavam sociedades muito diversas antes da colonização europeia."},{"heading":"Como compreender e aplicar","text":"Povos desenvolveram técnicas agrícolas, cidades, redes de troca, conhecimentos e tradições."}],"visual":{"icon":"🏛️","steps":["🏺","📜","🕰️"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Maias, astecas e incas possuíam organizações distintas. Não devemos tratar todos os povos indígenas como um único grupo."},{"title":"Veja outro exemplo","text":"Qual civilização construiu Machu Picchu? Resposta: Inca. A resposta correta é “Inca”. Considere o contexto histórico, as evidências e a época citada; evite generalizações."},{"title":"Teste sua compreensão","text":"Qual civilização desenvolveu cidades na Mesoamérica e calendários complexos? Resposta: Maia. A resposta correta é “Maia”. Considere o contexto histórico, as evidências e a época citada; evite generalizações."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Fontes históricas e tempo","summary":"Fontes históricas são vestígios interpretados para investigar o passado. Cronologias ajudam a ordenar eventos, mas processos podem ocorrer simultaneamente e em ritmos diferentes.","example":"Um diário expressa o ponto de vista de seu autor; compará-lo a outras fontes torna a interpretação mais cuidadosa.","sections":[{"heading":"Conceitos essenciais","text":"Fontes históricas são vestígios interpretados para investigar o passado."},{"heading":"Como compreender e aplicar","text":"Cronologias ajudam a ordenar eventos, mas processos podem ocorrer simultaneamente e em ritmos diferentes."}],"visual":{"icon":"🏛️","steps":["🏺","📜","🕰️"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Um diário expressa o ponto de vista de seu autor; compará-lo a outras fontes torna a interpretação mais cuidadosa."},{"title":"Veja outro exemplo","text":"Qual é uma fonte histórica escrita? Resposta: Carta antiga. A resposta é “Carta antiga”. Observe a definição ou a relação apresentada na pergunta."},{"title":"Teste sua compreensão","text":"Qual é uma fonte histórica oral? Resposta: Depoimento. A resposta é “Depoimento”. Observe a definição ou a relação apresentada na pergunta."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."},{"title":"Civilizações americanas antigas","summary":"Maias, astecas e incas construíram sociedades com conhecimentos e formas de organização próprios. O ambiente influenciou práticas agrícolas e a ocupação dos territórios.","example":"Machu Picchu está associado aos incas; Tenochtitlán foi capital do império asteca.","sections":[{"heading":"Conceitos essenciais","text":"Maias, astecas e incas construíram sociedades com conhecimentos e formas de organização próprios."},{"heading":"Como compreender e aplicar","text":"O ambiente influenciou práticas agrícolas e a ocupação dos territórios."}],"visual":{"icon":"🏛️","steps":["🏺","📜","🕰️"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Machu Picchu está associado aos incas; Tenochtitlán foi capital do império asteca."},{"title":"Veja outro exemplo","text":"Qual povo construiu Machu Picchu? Resposta: Incas. A resposta é “Incas”. Observe a definição ou a relação apresentada na pergunta."},{"title":"Teste sua compreensão","text":"Qual povo teve Tenochtitlán como capital? Resposta: Astecas. A resposta é “Astecas”. Observe a definição ou a relação apresentada na pergunta."}],"studyTip":"Considere quando e onde os acontecimentos ocorreram e quais fontes os explicam."}],[{"title":"Paisagens e espaço","summary":"Paisagem é o conjunto de elementos que podemos perceber em um lugar, incluindo componentes naturais e modificados pela sociedade. O espaço geográfico é produzido pelas relações entre natureza e ações humanas.","example":"Rios e montanhas são elementos naturais; ruas e edifícios são construções humanas.","sections":[{"heading":"Conceitos essenciais","text":"Paisagem é o conjunto de elementos que podemos perceber em um lugar, incluindo componentes naturais e modificados pela sociedade."},{"heading":"Como compreender e aplicar","text":"O espaço geográfico é produzido pelas relações entre natureza e ações humanas."}],"visual":{"icon":"🌎","steps":["🗺️","🌦️","🌿"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Rios e montanhas são elementos naturais; ruas e edifícios são construções humanas."},{"title":"Veja outro exemplo","text":"O que é paisagem geográfica? Resposta: conjunto de elementos percebidos em um lugar. A resposta correta é “conjunto de elementos percebidos em um lugar”. Associe o conceito geográfico às características da paisagem, do território ou do fenômeno descrito."},{"title":"Teste sua compreensão","text":"Qual é um elemento natural da paisagem? Resposta: rio. A resposta correta é “rio”. Associe o conceito geográfico às características da paisagem, do território ou do fenômeno descrito."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"Cartografia","summary":"Mapas representam espaços por símbolos, legendas, escalas e orientação. A rosa dos ventos indica direções; a escala relaciona distância no mapa e no terreno.","example":"Na escala 1:100.000, 1 cm no mapa representa 1 km na realidade.","sections":[{"heading":"Conceitos essenciais","text":"Mapas representam espaços por símbolos, legendas, escalas e orientação."},{"heading":"Como compreender e aplicar","text":"A rosa dos ventos indica direções; a escala relaciona distância no mapa e no terreno."}],"visual":{"icon":"🌎","steps":["🗺️","🌦️","🌿"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Na escala 1:100.000, 1 cm no mapa representa 1 km na realidade."},{"title":"Veja outro exemplo","text":"Qual direção fica oposta ao norte? Resposta: sul. A resposta correta é “sul”. Associe o conceito geográfico às características da paisagem, do território ou do fenômeno descrito."},{"title":"Teste sua compreensão","text":"Qual direção fica oposta ao leste? Resposta: oeste. A resposta correta é “oeste”. Associe o conceito geográfico às características da paisagem, do território ou do fenômeno descrito."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"Natureza e ambiente","summary":"O ambiente reúne ar, água, solo, seres vivos e suas interações. No ciclo da água, ocorrem evaporação, condensação, precipitação e infiltração.","example":"O vapor de água pode condensar formando gotículas que participam da formação de nuvens.","sections":[{"heading":"Conceitos essenciais","text":"O ambiente reúne ar, água, solo, seres vivos e suas interações."},{"heading":"Como compreender e aplicar","text":"No ciclo da água, ocorrem evaporação, condensação, precipitação e infiltração."}],"visual":{"icon":"🌎","steps":["🗺️","🌦️","🌿"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"O vapor de água pode condensar formando gotículas que participam da formação de nuvens."},{"title":"Veja outro exemplo","text":"Qual processo transforma água líquida em vapor? Resposta: evaporação. A resposta correta é “evaporação”. Associe o conceito geográfico às características da paisagem, do território ou do fenômeno descrito."},{"title":"Teste sua compreensão","text":"Qual processo forma gotas a partir do vapor? Resposta: condensação. A resposta correta é “condensação”. Associe o conceito geográfico às características da paisagem, do território ou do fenômeno descrito."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"Paisagem e espaço geográfico","summary":"As paisagens mudam com processos naturais e ações humanas. Fotografias, mapas e relatos permitem comparar transformações ao longo do tempo.","example":"A construção de uma estrada pode alterar o uso do solo, a circulação de pessoas e a vegetação.","sections":[{"heading":"Conceitos essenciais","text":"As paisagens mudam com processos naturais e ações humanas."},{"heading":"Como compreender e aplicar","text":"Fotografias, mapas e relatos permitem comparar transformações ao longo do tempo."}],"visual":{"icon":"🌎","steps":["🗺️","🌦️","🌿"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"A construção de uma estrada pode alterar o uso do solo, a circulação de pessoas e a vegetação."},{"title":"Veja outro exemplo","text":"O que é paisagem na Geografia? Resposta: Conjunto de elementos percebidos em um lugar. A resposta correta é “Conjunto de elementos percebidos em um lugar”. Associe o conceito geográfico às características da paisagem, do território ou do fenômeno descrito."},{"title":"Teste sua compreensão","text":"Qual elemento é natural em uma paisagem? Resposta: Rio. A resposta correta é “Rio”. Associe o conceito geográfico às características da paisagem, do território ou do fenômeno descrito."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"Cartografia e localização","summary":"Localização usa referências como pontos cardeais, coordenadas e mapas. Latitude é medida a partir do Equador; longitude, a partir de Greenwich.","example":"Um ponto a 20° S e 45° O está nos hemisférios Sul e Ocidental.","sections":[{"heading":"Conceitos essenciais","text":"Localização usa referências como pontos cardeais, coordenadas e mapas."},{"heading":"Como compreender e aplicar","text":"Latitude é medida a partir do Equador; longitude, a partir de Greenwich."}],"visual":{"icon":"🌎","steps":["🗺️","🌦️","🌿"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Um ponto a 20° S e 45° O está nos hemisférios Sul e Ocidental."},{"title":"Veja outro exemplo","text":"Qual direção fica oposta ao norte? Resposta: Sul. A resposta correta é “Sul”. Associe o conceito geográfico às características da paisagem, do território ou do fenômeno descrito."},{"title":"Teste sua compreensão","text":"Qual direção fica oposta ao leste? Resposta: Oeste. A resposta correta é “Oeste”. Associe o conceito geográfico às características da paisagem, do território ou do fenômeno descrito."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"Clima e atmosfera","summary":"Tempo atmosférico descreve condições de curto prazo; clima é o comportamento habitual dessas condições em períodos longos. Temperatura, chuva, ventos e umidade variam entre regiões.","example":"Um dia frio não prova mudança no clima de uma região; é preciso observar dados de muitos anos.","sections":[{"heading":"Conceitos essenciais","text":"Tempo atmosférico descreve condições de curto prazo; clima é o comportamento habitual dessas condições em períodos longos."},{"heading":"Como compreender e aplicar","text":"Temperatura, chuva, ventos e umidade variam entre regiões."}],"visual":{"icon":"🌎","steps":["🗺️","🌦️","🌿"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Um dia frio não prova mudança no clima de uma região; é preciso observar dados de muitos anos."},{"title":"Veja outro exemplo","text":"O que é tempo atmosférico? Resposta: Condição da atmosfera em determinado momento. A resposta correta é “Condição da atmosfera em determinado momento”. Associe o conceito geográfico às características da paisagem, do território ou do fenômeno descrito."},{"title":"Teste sua compreensão","text":"O que é clima? Resposta: Padrão das condições atmosféricas ao longo de muitos anos. A resposta correta é “Padrão das condições atmosféricas ao longo de muitos anos”. Associe o conceito geográfico às características da paisagem, do território ou do fenômeno descrito."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"Relevo, solo e água","summary":"Relevo reúne formas da superfície terrestre, como planaltos, planícies e depressões. Água, vento e gravidade participam da erosão; vegetação ajuda a proteger o solo.","example":"Em encostas desmatadas, chuvas intensas podem favorecer erosão e deslizamentos.","sections":[{"heading":"Conceitos essenciais","text":"Relevo reúne formas da superfície terrestre, como planaltos, planícies e depressões."},{"heading":"Como compreender e aplicar","text":"Água, vento e gravidade participam da erosão; vegetação ajuda a proteger o solo."}],"visual":{"icon":"🌎","steps":["🗺️","🌦️","🌿"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Em encostas desmatadas, chuvas intensas podem favorecer erosão e deslizamentos."},{"title":"Veja outro exemplo","text":"Qual forma de relevo apresenta altitude relativamente elevada e superfície variada? Resposta: Planalto. A resposta correta é “Planalto”. Associe o conceito geográfico às características da paisagem, do território ou do fenômeno descrito."},{"title":"Teste sua compreensão","text":"Qual forma de relevo é geralmente associada a superfícies mais planas de deposição? Resposta: Planície. A resposta correta é “Planície”. Associe o conceito geográfico às características da paisagem, do território ou do fenômeno descrito."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"Sustentabilidade e recursos","summary":"Recursos naturais são utilizados pelas sociedades, mas podem ser esgotados ou degradados. Sustentabilidade envolve reduzir desperdícios, reutilizar materiais e cuidar dos ecossistemas.","example":"Economizar água e diminuir resíduos são atitudes que reduzem impactos ambientais.","sections":[{"heading":"Conceitos essenciais","text":"Recursos naturais são utilizados pelas sociedades, mas podem ser esgotados ou degradados."},{"heading":"Como compreender e aplicar","text":"Sustentabilidade envolve reduzir desperdícios, reutilizar materiais e cuidar dos ecossistemas."}],"visual":{"icon":"🌎","steps":["🗺️","🌦️","🌿"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Economizar água e diminuir resíduos são atitudes que reduzem impactos ambientais."},{"title":"Veja outro exemplo","text":"Qual recurso é renovável em escala humana quando bem manejado? Resposta: Energia solar. A resposta correta é “Energia solar”. Associe o conceito geográfico às características da paisagem, do território ou do fenômeno descrito."},{"title":"Teste sua compreensão","text":"Qual fonte energética utiliza ventos? Resposta: Eólica. A resposta correta é “Eólica”. Associe o conceito geográfico às características da paisagem, do território ou do fenômeno descrito."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"Coordenadas e cartografia","summary":"Coordenadas geográficas permitem localizar pontos por latitude e longitude. Mapas temáticos destacam fenômenos específicos, como população, vegetação ou chuvas.","example":"Latitude 0° corresponde ao Equador; longitude 0° corresponde ao meridiano de Greenwich.","sections":[{"heading":"Conceitos essenciais","text":"Coordenadas geográficas permitem localizar pontos por latitude e longitude."},{"heading":"Como compreender e aplicar","text":"Mapas temáticos destacam fenômenos específicos, como população, vegetação ou chuvas."}],"visual":{"icon":"🌎","steps":["🗺️","🌦️","🌿"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Latitude 0° corresponde ao Equador; longitude 0° corresponde ao meridiano de Greenwich."},{"title":"Veja outro exemplo","text":"Qual linha divide a Terra em hemisférios Norte e Sul? Resposta: Equador. A resposta é “Equador”. Observe a definição ou a relação apresentada na pergunta."},{"title":"Teste sua compreensão","text":"Qual meridiano é referência para as longitudes? Resposta: Greenwich. A resposta é “Greenwich”. Observe a definição ou a relação apresentada na pergunta."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."},{"title":"População e espaço geográfico","summary":"A população ocupa e transforma espaços. Migração é deslocamento de pessoas entre lugares; urbanização envolve o crescimento e a concentração de atividades urbanas.","example":"Crescimento urbano sem saneamento adequado pode causar impactos ambientais e problemas de saúde.","sections":[{"heading":"Conceitos essenciais","text":"A população ocupa e transforma espaços."},{"heading":"Como compreender e aplicar","text":"Migração é deslocamento de pessoas entre lugares; urbanização envolve o crescimento e a concentração de atividades urbanas."}],"visual":{"icon":"🌎","steps":["🗺️","🌦️","🌿"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Crescimento urbano sem saneamento adequado pode causar impactos ambientais e problemas de saúde."},{"title":"Veja outro exemplo","text":"O que é migração? Resposta: Deslocamento de pessoas entre lugares. A resposta é “Deslocamento de pessoas entre lugares”. Observe a definição ou a relação apresentada na pergunta."},{"title":"Teste sua compreensão","text":"O que é urbanização? Resposta: Crescimento da população e dos espaços urbanos. A resposta é “Crescimento da população e dos espaços urbanos”. Observe a definição ou a relação apresentada na pergunta."}],"studyTip":"Observe as relações entre natureza e sociedade e procure exemplos do cotidiano."}],[{"title":"Vocabulário","summary":"Aprender vocabulário em inglês fica mais fácil quando relacionamos palavras a situações reais. Observe substantivos, verbos e expressões usadas em casa, na escola e na cidade.","example":"Book significa livro; school significa escola. Em 'Open your book', a instrução é abrir o livro.","sections":[{"heading":"Conceitos essenciais","text":"Aprender vocabulário em inglês fica mais fácil quando relacionamos palavras a situações reais."},{"heading":"Como compreender e aplicar","text":"Observe substantivos, verbos e expressões usadas em casa, na escola e na cidade."}],"visual":{"icon":"💬","steps":["🔤","🗣️","💬"],"labels":["OBSERVAR","PRATICAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Book significa livro; school significa escola. Em 'Open your book', a instrução é abrir o livro."},{"title":"Veja outro exemplo","text":"Como se diz “livro” em inglês? Resposta: book. A resposta correta é “book”. Compare o significado e a estrutura gramatical da expressão em inglês."},{"title":"Teste sua compreensão","text":"Como se diz “escola” em inglês? Resposta: school. A resposta correta é “school”. Compare o significado e a estrutura gramatical da expressão em inglês."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Verbo to be","summary":"O verbo to be pode significar ser ou estar. No presente, usamos am com I, is com he/she/it e are com you/we/they.","example":"I am a student. She is happy. They are friends. Na pergunta, invertemos: 'Is she happy?'.","sections":[{"heading":"Conceitos essenciais","text":"O verbo to be pode significar ser ou estar."},{"heading":"Como compreender e aplicar","text":"No presente, usamos am com I, is com he/she/it e are com you/we/they."}],"visual":{"icon":"💬","steps":["🔤","🗣️","💬"],"labels":["LER","PRATICAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"I am a student. She is happy. They are friends. Na pergunta, invertemos: 'Is she happy?'."},{"title":"Veja outro exemplo","text":"Complete: I ___ a student. Resposta: am. A resposta correta é “am”. Compare o significado e a estrutura gramatical da expressão em inglês."},{"title":"Teste sua compreensão","text":"Complete: She ___ happy. Resposta: is. A resposta correta é “is”. Compare o significado e a estrutura gramatical da expressão em inglês."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Simple present","summary":"O simple present descreve hábitos, rotinas e fatos gerais. Com he, she e it, muitos verbos recebem -s ou -es. Em negativas e perguntas, usamos do/does.","example":"She plays soccer. Does she play soccer? They do not play on Mondays.","sections":[{"heading":"Conceitos essenciais","text":"O simple present descreve hábitos, rotinas e fatos gerais. Com he, she e it, muitos verbos recebem -s ou -es."},{"heading":"Como compreender e aplicar","text":"Em negativas e perguntas, usamos do/does."}],"visual":{"icon":"💬","steps":["🔤","🗣️","💬"],"labels":["OBSERVAR","PRATICAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"She plays soccer. Does she play soccer? They do not play on Mondays."},{"title":"Veja outro exemplo","text":"Complete: She ___ soccer every day. Resposta: plays. A resposta correta é “plays”. Compare o significado e a estrutura gramatical da expressão em inglês."},{"title":"Teste sua compreensão","text":"Complete: They ___ English. Resposta: study. A resposta correta é “study”. Compare o significado e a estrutura gramatical da expressão em inglês."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Cumprimentos e apresentações","summary":"Cumprimentos variam conforme o momento e a situação. Ao conhecer alguém, podemos perguntar o nome e responder com educação.","example":"Good morning = bom dia; Nice to meet you = prazer em conhecer você; My name is Ana = meu nome é Ana.","sections":[{"heading":"Conceitos essenciais","text":"Cumprimentos variam conforme o momento e a situação."},{"heading":"Como compreender e aplicar","text":"Ao conhecer alguém, podemos perguntar o nome e responder com educação."}],"visual":{"icon":"💬","steps":["🔤","🗣️","💬"],"labels":["LER","PRATICAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Good morning = bom dia; Nice to meet you = prazer em conhecer você; My name is Ana = meu nome é Ana."},{"title":"Veja outro exemplo","text":"Como se diz “bom dia” em inglês? Resposta: Good morning. A resposta correta é “Good morning”. Compare o significado e a estrutura gramatical da expressão em inglês."},{"title":"Teste sua compreensão","text":"Como se diz “boa noite” ao se despedir para dormir? Resposta: Good night. A resposta correta é “Good night”. Compare o significado e a estrutura gramatical da expressão em inglês."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Família, escola e cotidiano","summary":"Palavras sobre família, escola e rotina ajudam a compreender pequenos textos. O contexto da frase indica quem pratica a ação e quando.","example":"Mother = mãe; brother = irmão; breakfast = café da manhã; 'I go to school' = eu vou à escola.","sections":[{"heading":"Conceitos essenciais","text":"Palavras sobre família, escola e rotina ajudam a compreender pequenos textos."},{"heading":"Como compreender e aplicar","text":"O contexto da frase indica quem pratica a ação e quando."}],"visual":{"icon":"💬","steps":["🔤","🗣️","💬"],"labels":["OBSERVAR","PRATICAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Mother = mãe; brother = irmão; breakfast = café da manhã; 'I go to school' = eu vou à escola."},{"title":"Veja outro exemplo","text":"Qual é a tradução de “mother”? Resposta: Mãe. A resposta correta é “Mãe”. Compare o significado e a estrutura gramatical da expressão em inglês."},{"title":"Teste sua compreensão","text":"Qual é a tradução de “brother”? Resposta: Irmão. A resposta correta é “Irmão”. Compare o significado e a estrutura gramatical da expressão em inglês."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Pronomes e verbo to be","summary":"Pronomes pessoais substituem nomes: I, you, he, she, it, we, they. Cada grupo combina com uma forma do verbo to be.","example":"We are students; He is my brother; I am at home.","sections":[{"heading":"Conceitos essenciais","text":"Pronomes pessoais substituem nomes: I, you, he, she, it, we, they."},{"heading":"Como compreender e aplicar","text":"Cada grupo combina com uma forma do verbo to be."}],"visual":{"icon":"💬","steps":["🔤","🗣️","💬"],"labels":["LER","PRATICAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"We are students; He is my brother; I am at home."},{"title":"Veja outro exemplo","text":"Qual pronome significa “ela”? Resposta: She. A resposta correta é “She”. Compare o significado e a estrutura gramatical da expressão em inglês."},{"title":"Teste sua compreensão","text":"Qual pronome significa “nós”? Resposta: We. A resposta correta é “We”. Compare o significado e a estrutura gramatical da expressão em inglês."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Presente simples e perguntas","summary":"No presente simples, perguntas com verbos comuns geralmente usam do ou does. Com he/she/it, use does e o verbo principal sem -s.","example":"Does she like music? Yes, she does. Do they study? Yes, they do.","sections":[{"heading":"Conceitos essenciais","text":"No presente simples, perguntas com verbos comuns geralmente usam do ou does."},{"heading":"Como compreender e aplicar","text":"Com he/she/it, use does e o verbo principal sem -s."}],"visual":{"icon":"💬","steps":["🔤","🗣️","💬"],"labels":["OBSERVAR","PRATICAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Does she like music? Yes, she does. Do they study? Yes, they do."},{"title":"Veja outro exemplo","text":"Qual frase está no presente simples correto? Resposta: She plays soccer.. A resposta correta é “She plays soccer.”. Compare o significado e a estrutura gramatical da expressão em inglês."},{"title":"Teste sua compreensão","text":"Qual auxiliar forma pergunta com “you” no presente simples? Resposta: Do. A resposta correta é “Do”. Compare o significado e a estrutura gramatical da expressão em inglês."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Leitura e cultura em inglês","summary":"Ler em inglês exige observar palavras conhecidas, contexto e finalidade do texto. Placas, convites, bilhetes e horários ajudam a praticar compreensão.","example":"'The museum opens at nine' informa o horário de abertura do museu: nove horas.","sections":[{"heading":"Conceitos essenciais","text":"Ler em inglês exige observar palavras conhecidas, contexto e finalidade do texto."},{"heading":"Como compreender e aplicar","text":"Placas, convites, bilhetes e horários ajudam a praticar compreensão."}],"visual":{"icon":"💬","steps":["🔤","🗣️","💬"],"labels":["LER","PRATICAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"'The museum opens at nine' informa o horário de abertura do museu: nove horas."},{"title":"Veja outro exemplo","text":"O que significa “Open the door”? Resposta: Abra a porta. A resposta correta é “Abra a porta”. Compare o significado e a estrutura gramatical da expressão em inglês."},{"title":"Teste sua compreensão","text":"O que significa “Read the text”? Resposta: Leia o texto. A resposta correta é “Leia o texto”. Compare o significado e a estrutura gramatical da expressão em inglês."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Leitura e comunicação cotidiana","summary":"Comunicar-se em inglês envolve compreender perguntas frequentes, instruções e respostas adequadas. Não é necessário traduzir palavra por palavra para entender a mensagem.","example":"'How often do you read?' pergunta sobre frequência. Uma resposta possível é 'Every day'.","sections":[{"heading":"Conceitos essenciais","text":"Comunicar-se em inglês envolve compreender perguntas frequentes, instruções e respostas adequadas."},{"heading":"Como compreender e aplicar","text":"Não é necessário traduzir palavra por palavra para entender a mensagem."}],"visual":{"icon":"💬","steps":["🔤","🗣️","💬"],"labels":["OBSERVAR","PRATICAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"'How often do you read?' pergunta sobre frequência. Uma resposta possível é 'Every day'."},{"title":"Veja outro exemplo","text":"What does “Good morning” mean? Resposta: Bom dia. A resposta é “Bom dia”. Observe a definição ou a relação apresentada na pergunta."},{"title":"Teste sua compreensão","text":"What does “Thank you” mean? Resposta: Obrigado(a). A resposta é “Obrigado(a)”. Observe a definição ou a relação apresentada na pergunta."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."},{"title":"Preposições e localização","summary":"Preposições indicam relações de lugar: in (dentro), on (sobre), under (embaixo), between (entre), behind (atrás) e next to (ao lado).","example":"'The cat is under the table' significa que o gato está embaixo da mesa.","sections":[{"heading":"Conceitos essenciais","text":"Preposições indicam relações de lugar: in (dentro), on (sobre), under (embaixo), between (entre), behind (atrás) e next to (ao lado)."},{"heading":"Como compreender e aplicar","text":"Observe a situação, identifique os dados importantes e relacione-os aos conceitos apresentados."}],"visual":{"icon":"💬","steps":["🔤","🗣️","💬"],"labels":["LER","PRATICAR","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"'The cat is under the table' significa que o gato está embaixo da mesa."},{"title":"Veja outro exemplo","text":"What does “under the table” mean? Resposta: Debaixo da mesa. A resposta é “Debaixo da mesa”. Observe a definição ou a relação apresentada na pergunta."},{"title":"Teste sua compreensão","text":"What does “on the desk” mean? Resposta: Sobre a carteira. A resposta é “Sobre a carteira”. Observe a definição ou a relação apresentada na pergunta."}],"studyTip":"Leia a frase completa, observe o contexto e pratique a expressão em voz alta."}],[{"title":"Artes visuais e música","summary":"As artes utilizam linguagens e elementos expressivos. Nas artes visuais, linha, forma, cor e textura criam sentidos; na música, ritmo, melodia, intensidade e timbre organizam sons.","example":"Linhas diagonais podem sugerir movimento; sons fortes e suaves criam contrastes musicais.","sections":[{"heading":"Conceitos essenciais","text":"As artes utilizam linguagens e elementos expressivos."},{"heading":"Como compreender e aplicar","text":"Nas artes visuais, linha, forma, cor e textura criam sentidos; na música, ritmo, melodia, intensidade e timbre organizam sons."}],"visual":{"icon":"🎨","steps":["🎭","🎨","🎵"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Linhas diagonais podem sugerir movimento; sons fortes e suaves criam contrastes musicais."},{"title":"Veja outro exemplo","text":"Quais são as cores primárias na pintura tradicional? Resposta: vermelho, amarelo e azul. A resposta correta é “vermelho, amarelo e azul”. Identifique a linguagem artística e o elemento expressivo solicitado."},{"title":"Teste sua compreensão","text":"Qual elemento visual delimita formas? Resposta: linha. A resposta correta é “linha”. Identifique a linguagem artística e o elemento expressivo solicitado."}],"studyTip":"Observe os elementos expressivos e pense nas escolhas feitas por quem criou a obra."},{"title":"Artes visuais","summary":"Desenho, pintura, escultura, fotografia e outras formas visuais expressam ideias. Artistas escolhem materiais, cores, enquadramentos e composições para criar efeitos.","example":"Uma pintura com cores frias pode transmitir uma sensação diferente de outra com cores quentes.","sections":[{"heading":"Conceitos essenciais","text":"Desenho, pintura, escultura, fotografia e outras formas visuais expressam ideias."},{"heading":"Como compreender e aplicar","text":"Artistas escolhem materiais, cores, enquadramentos e composições para criar efeitos."}],"visual":{"icon":"🎨","steps":["🎭","🎨","🎵"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Uma pintura com cores frias pode transmitir uma sensação diferente de outra com cores quentes."},{"title":"Veja outro exemplo","text":"Qual é uma linguagem das artes visuais? Resposta: Pintura. A resposta correta é “Pintura”. Identifique a linguagem artística e o elemento expressivo solicitado."},{"title":"Teste sua compreensão","text":"Qual elemento visual define contornos? Resposta: Linha. A resposta correta é “Linha”. Identifique a linguagem artística e o elemento expressivo solicitado."}],"studyTip":"Observe os elementos expressivos e pense nas escolhas feitas por quem criou a obra."},{"title":"Música","summary":"Música combina sons e silêncios. Ritmo organiza durações; altura distingue graves e agudos; intensidade distingue fortes e suaves; timbre diferencia fontes sonoras.","example":"Um tambor e uma flauta podem tocar a mesma nota percebida com timbres diferentes.","sections":[{"heading":"Conceitos essenciais","text":"Música combina sons e silêncios."},{"heading":"Como compreender e aplicar","text":"Ritmo organiza durações; altura distingue graves e agudos; intensidade distingue fortes e suaves; timbre diferencia fontes sonoras."}],"visual":{"icon":"🎨","steps":["🎭","🎨","🎵"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Um tambor e uma flauta podem tocar a mesma nota percebida com timbres diferentes."},{"title":"Veja outro exemplo","text":"Qual elemento musical indica a duração dos sons? Resposta: Ritmo. A resposta correta é “Ritmo”. Identifique a linguagem artística e o elemento expressivo solicitado."},{"title":"Teste sua compreensão","text":"Qual elemento distingue sons graves e agudos? Resposta: Altura. A resposta correta é “Altura”. Identifique a linguagem artística e o elemento expressivo solicitado."}],"studyTip":"Observe os elementos expressivos e pense nas escolhas feitas por quem criou a obra."},{"title":"Teatro e dança","summary":"Teatro reúne personagens, interpretação, cenário, figurino e expressão corporal. A dança utiliza corpo, espaço, tempo e ritmo para criar movimentos e sentidos.","example":"Uma personagem pode comunicar medo com gestos e expressão facial, mesmo sem falar.","sections":[{"heading":"Conceitos essenciais","text":"Teatro reúne personagens, interpretação, cenário, figurino e expressão corporal."},{"heading":"Como compreender e aplicar","text":"A dança utiliza corpo, espaço, tempo e ritmo para criar movimentos e sentidos."}],"visual":{"icon":"🎨","steps":["🎭","🎨","🎵"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Uma personagem pode comunicar medo com gestos e expressão facial, mesmo sem falar."},{"title":"Veja outro exemplo","text":"Quem interpreta personagens no teatro? Resposta: Ator ou atriz. A resposta correta é “Ator ou atriz”. Identifique a linguagem artística e o elemento expressivo solicitado."},{"title":"Teste sua compreensão","text":"Qual elemento indica o lugar da ação teatral? Resposta: Cenário. A resposta correta é “Cenário”. Identifique a linguagem artística e o elemento expressivo solicitado."}],"studyTip":"Observe os elementos expressivos e pense nas escolhas feitas por quem criou a obra."},{"title":"Patrimônio e cultura","summary":"Patrimônio cultural inclui bens materiais, como edifícios e objetos, e imateriais, como saberes, festas e práticas transmitidas entre gerações.","example":"Uma construção histórica é bem material; uma tradição de dança pode ser patrimônio imaterial.","sections":[{"heading":"Conceitos essenciais","text":"Patrimônio cultural inclui bens materiais, como edifícios e objetos, e imateriais, como saberes, festas e práticas transmitidas entre gerações."},{"heading":"Como compreender e aplicar","text":"Observe a situação, identifique os dados importantes e relacione-os aos conceitos apresentados."}],"visual":{"icon":"🎨","steps":["🎭","🎨","🎵"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Uma construção histórica é bem material; uma tradição de dança pode ser patrimônio imaterial."},{"title":"Veja outro exemplo","text":"O que é patrimônio cultural material? Resposta: Bens físicos de valor cultural. A resposta correta é “Bens físicos de valor cultural”. Identifique a linguagem artística e o elemento expressivo solicitado."},{"title":"Teste sua compreensão","text":"O que é patrimônio cultural imaterial? Resposta: Saberes, festas e práticas. A resposta correta é “Saberes, festas e práticas”. Identifique a linguagem artística e o elemento expressivo solicitado."}],"studyTip":"Observe os elementos expressivos e pense nas escolhas feitas por quem criou a obra."},{"title":"Criação e interpretação","summary":"Criar arte envolve pesquisar, experimentar, esboçar, produzir e refletir sobre escolhas. Interpretar uma obra requer observar elementos e considerar contexto e diferentes pontos de vista.","example":"Antes de um mural, um esboço ajuda a organizar formas e cores.","sections":[{"heading":"Conceitos essenciais","text":"Criar arte envolve pesquisar, experimentar, esboçar, produzir e refletir sobre escolhas."},{"heading":"Como compreender e aplicar","text":"Interpretar uma obra requer observar elementos e considerar contexto e diferentes pontos de vista."}],"visual":{"icon":"🎨","steps":["🎭","🎨","🎵"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Antes de um mural, um esboço ajuda a organizar formas e cores."},{"title":"Veja outro exemplo","text":"Qual etapa inicia muitos projetos artísticos? Resposta: Pesquisa de referências. A resposta correta é “Pesquisa de referências”. Identifique a linguagem artística e o elemento expressivo solicitado."},{"title":"Teste sua compreensão","text":"O que é esboço? Resposta: Desenho inicial de uma ideia. A resposta correta é “Desenho inicial de uma ideia”. Identifique a linguagem artística e o elemento expressivo solicitado."}],"studyTip":"Observe os elementos expressivos e pense nas escolhas feitas por quem criou a obra."},{"title":"Patrimônio cultural e manifestações","summary":"Manifestações culturais expressam memórias e identidades de grupos. Respeitar origens e praticantes é essencial para conhecer e valorizar a diversidade.","example":"Capoeira combina movimentos, música e saberes históricos compartilhados.","sections":[{"heading":"Conceitos essenciais","text":"Manifestações culturais expressam memórias e identidades de grupos."},{"heading":"Como compreender e aplicar","text":"Respeitar origens e praticantes é essencial para conhecer e valorizar a diversidade."}],"visual":{"icon":"🎨","steps":["🎭","🎨","🎵"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Capoeira combina movimentos, música e saberes históricos compartilhados."},{"title":"Veja outro exemplo","text":"O que é patrimônio cultural material? Resposta: Construções e objetos de valor cultural. A resposta é “Construções e objetos de valor cultural”. Observe a definição ou a relação apresentada na pergunta."},{"title":"Teste sua compreensão","text":"Qual exemplo é patrimônio imaterial? Resposta: Uma tradição oral. A resposta é “Uma tradição oral”. Observe a definição ou a relação apresentada na pergunta."}],"studyTip":"Observe os elementos expressivos e pense nas escolhas feitas por quem criou a obra."}],[{"title":"Jogos e esportes","summary":"Jogos e esportes envolvem regras, estratégias, cooperação e respeito. Vencer não justifica desrespeitar colegas ou alterar regras de forma injusta.","example":"No jogo coletivo, comunicação e ocupação de espaços ajudam a equipe.","sections":[{"heading":"Conceitos essenciais","text":"Jogos e esportes envolvem regras, estratégias, cooperação e respeito."},{"heading":"Como compreender e aplicar","text":"Vencer não justifica desrespeitar colegas ou alterar regras de forma injusta."}],"visual":{"icon":"🏃","steps":["🤸","🏅","🤝"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"No jogo coletivo, comunicação e ocupação de espaços ajudam a equipe."},{"title":"Veja outro exemplo","text":"Qual prática exige cooperação e respeito às regras? Resposta: jogo coletivo. A resposta correta é “jogo coletivo”. Considere as regras, o movimento corporal e o respeito aos participantes."},{"title":"Teste sua compreensão","text":"Qual esporte utiliza rede e bola rebatida com as mãos? Resposta: voleibol. A resposta correta é “voleibol”. Considere as regras, o movimento corporal e o respeito aos participantes."}],"studyTip":"Pense nas regras, na segurança, na cooperação e nas estratégias da prática corporal."},{"title":"Corpo e movimento","summary":"Movimentos exigem coordenação, equilíbrio, agilidade, força, resistência e flexibilidade em diferentes combinações. As capacidades podem ser desenvolvidas com prática adequada.","example":"Equilibrar-se em uma linha exige controle corporal; mudar rapidamente de direção exige agilidade.","sections":[{"heading":"Conceitos essenciais","text":"Movimentos exigem coordenação, equilíbrio, agilidade, força, resistência e flexibilidade em diferentes combinações."},{"heading":"Como compreender e aplicar","text":"As capacidades podem ser desenvolvidas com prática adequada."}],"visual":{"icon":"🏃","steps":["🤸","🏅","🤝"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Equilibrar-se em uma linha exige controle corporal; mudar rapidamente de direção exige agilidade."},{"title":"Veja outro exemplo","text":"Qual capacidade permite manter equilíbrio corporal? Resposta: equilíbrio. A resposta correta é “equilíbrio”. Considere as regras, o movimento corporal e o respeito aos participantes."},{"title":"Teste sua compreensão","text":"Qual capacidade permite mudar rapidamente de direção? Resposta: agilidade. A resposta correta é “agilidade”. Considere as regras, o movimento corporal e o respeito aos participantes."}],"studyTip":"Pense nas regras, na segurança, na cooperação e nas estratégias da prática corporal."},{"title":"Jogos e brincadeiras","summary":"Brincadeiras são práticas culturais que podem mudar conforme o grupo e o lugar. Jogos cooperativos valorizam objetivos compartilhados e a participação de todos.","example":"Adaptar regras para incluir colegas pode tornar a brincadeira mais acessível e justa.","sections":[{"heading":"Conceitos essenciais","text":"Brincadeiras são práticas culturais que podem mudar conforme o grupo e o lugar."},{"heading":"Como compreender e aplicar","text":"Jogos cooperativos valorizam objetivos compartilhados e a participação de todos."}],"visual":{"icon":"🏃","steps":["🤸","🏅","🤝"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Adaptar regras para incluir colegas pode tornar a brincadeira mais acessível e justa."},{"title":"Veja outro exemplo","text":"Qual é uma característica dos jogos cooperativos? Resposta: Objetivo comum entre participantes. A resposta correta é “Objetivo comum entre participantes”. Considere as regras, o movimento corporal e o respeito aos participantes."},{"title":"Teste sua compreensão","text":"Qual atitude demonstra respeito durante um jogo? Resposta: Cumprir regras combinadas. A resposta correta é “Cumprir regras combinadas”. Considere as regras, o movimento corporal e o respeito aos participantes."}],"studyTip":"Pense nas regras, na segurança, na cooperação e nas estratégias da prática corporal."},{"title":"Esportes de marca e precisão","summary":"Nos esportes de marca, o resultado depende de tempo, distância ou altura. Nos de precisão, o objetivo é atingir um alvo com controle.","example":"Corrida e salto são exemplos de marca; boliche e tiro com arco são exemplos de precisão.","sections":[{"heading":"Conceitos essenciais","text":"Nos esportes de marca, o resultado depende de tempo, distância ou altura."},{"heading":"Como compreender e aplicar","text":"Nos de precisão, o objetivo é atingir um alvo com controle."}],"visual":{"icon":"🏃","steps":["🤸","🏅","🤝"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Corrida e salto são exemplos de marca; boliche e tiro com arco são exemplos de precisão."},{"title":"Veja outro exemplo","text":"Qual esporte é de marca? Resposta: Corrida de velocidade. A resposta correta é “Corrida de velocidade”. Considere as regras, o movimento corporal e o respeito aos participantes."},{"title":"Teste sua compreensão","text":"Qual esporte é de precisão? Resposta: Bocha. A resposta correta é “Bocha”. Considere as regras, o movimento corporal e o respeito aos participantes."}],"studyTip":"Pense nas regras, na segurança, na cooperação e nas estratégias da prática corporal."},{"title":"Esportes de invasão e rede","summary":"Esportes de invasão envolvem avançar sobre um espaço defendido pelo adversário; esportes de rede dividem áreas por uma rede ou obstáculo semelhante.","example":"Handebol é esporte de invasão; voleibol é esporte de rede.","sections":[{"heading":"Conceitos essenciais","text":"Esportes de invasão envolvem avançar sobre um espaço defendido pelo adversário; esportes de rede dividem áreas por uma rede ou obstáculo semelhante."},{"heading":"Como compreender e aplicar","text":"Observe a situação, identifique os dados importantes e relacione-os aos conceitos apresentados."}],"visual":{"icon":"🏃","steps":["🤸","🏅","🤝"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Handebol é esporte de invasão; voleibol é esporte de rede."},{"title":"Veja outro exemplo","text":"Qual é um esporte de invasão? Resposta: Futebol. A resposta correta é “Futebol”. Considere as regras, o movimento corporal e o respeito aos participantes."},{"title":"Teste sua compreensão","text":"Qual é um esporte de rede? Resposta: Voleibol. A resposta correta é “Voleibol”. Considere as regras, o movimento corporal e o respeito aos participantes."}],"studyTip":"Pense nas regras, na segurança, na cooperação e nas estratégias da prática corporal."},{"title":"Ginásticas e saúde","summary":"Ginásticas podem desenvolver força, equilíbrio, coordenação e flexibilidade. Praticar com segurança inclui aquecimento, hidratação, descanso e respeito aos limites do corpo.","example":"Alongar-se gradualmente pode trabalhar a amplitude de movimento sem forçar até sentir dor.","sections":[{"heading":"Conceitos essenciais","text":"Ginásticas podem desenvolver força, equilíbrio, coordenação e flexibilidade."},{"heading":"Como compreender e aplicar","text":"Praticar com segurança inclui aquecimento, hidratação, descanso e respeito aos limites do corpo."}],"visual":{"icon":"🏃","steps":["🤸","🏅","🤝"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Alongar-se gradualmente pode trabalhar a amplitude de movimento sem forçar até sentir dor."},{"title":"Veja outro exemplo","text":"Qual capacidade física está ligada à amplitude de movimentos? Resposta: Flexibilidade. A resposta correta é “Flexibilidade”. Considere as regras, o movimento corporal e o respeito aos participantes."},{"title":"Teste sua compreensão","text":"Qual capacidade física ajuda a manter esforço por mais tempo? Resposta: Resistência. A resposta correta é “Resistência”. Considere as regras, o movimento corporal e o respeito aos participantes."}],"studyTip":"Pense nas regras, na segurança, na cooperação e nas estratégias da prática corporal."},{"title":"Danças e aventuras","summary":"Dança combina movimentos, ritmo, espaço e expressão cultural. Práticas corporais de aventura exigem planejamento, cuidado com o ambiente e avaliação de riscos.","example":"Antes de uma trilha, confira percurso, clima, equipamentos e hidratação.","sections":[{"heading":"Conceitos essenciais","text":"Dança combina movimentos, ritmo, espaço e expressão cultural."},{"heading":"Como compreender e aplicar","text":"Práticas corporais de aventura exigem planejamento, cuidado com o ambiente e avaliação de riscos."}],"visual":{"icon":"🏃","steps":["🤸","🏅","🤝"],"labels":["OBSERVAR","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"Antes de uma trilha, confira percurso, clima, equipamentos e hidratação."},{"title":"Veja outro exemplo","text":"Qual elemento faz parte da dança? Resposta: Ritmo. A resposta correta é “Ritmo”. Considere as regras, o movimento corporal e o respeito aos participantes."},{"title":"Teste sua compreensão","text":"Qual dança é associada à cultura urbana? Resposta: Breaking. A resposta correta é “Breaking”. Considere as regras, o movimento corporal e o respeito aos participantes."}],"studyTip":"Pense nas regras, na segurança, na cooperação e nas estratégias da prática corporal."},{"title":"Esportes de invasão e precisão","summary":"Esportes de invasão exigem estratégias coletivas para avançar e defender; esportes de precisão valorizam controle para atingir alvos.","example":"No futsal, passes e movimentação criam oportunidades; no boliche, direção e força do lançamento influenciam a precisão.","sections":[{"heading":"Conceitos essenciais","text":"Esportes de invasão exigem estratégias coletivas para avançar e defender; esportes de precisão valorizam controle para atingir alvos."},{"heading":"Como compreender e aplicar","text":"Observe a situação, identifique os dados importantes e relacione-os aos conceitos apresentados."}],"visual":{"icon":"🏃","steps":["🤸","🏅","🤝"],"labels":["LER","COMPREENDER","APLICAR"]},"examples":[{"title":"Exemplo explicado","text":"No futsal, passes e movimentação criam oportunidades; no boliche, direção e força do lançamento influenciam a precisão."},{"title":"Veja outro exemplo","text":"Qual é um esporte de invasão? Resposta: Handebol. A resposta é “Handebol”. Observe a definição ou a relação apresentada na pergunta."},{"title":"Teste sua compreensão","text":"Qual é um esporte de precisão? Resposta: Bocha. A resposta é “Bocha”. Observe a definição ou a relação apresentada na pergunta."}],"studyTip":"Pense nas regras, na segurança, na cooperação e nas estratégias da prática corporal."}]];